import { test, expect, type APIRequestContext } from '@playwright/test';

const PNG_32X32 = Buffer.from(
  'iVBORw0KGgoAAAANSUhEUgAAACAAAAAgCAIAAAD8GO2jAAAAKklEQVR4nGP4Yh9HU8QwasGoBaMWjFowasGoBaMWjFowasGoBaMWDBULAN4gRFtH0KHXAAAAAElFTkSuQmCC',
  'base64'
);

function makeEmail(prefix: string): string {
  const rand = Math.random().toString(36).slice(2, 7);
  return `${prefix}-${Date.now()}-${rand}@example.com`;
}

async function loginUser(request: APIRequestContext, email: string, nickname: string) {
  const sendRes = await request.post('/api/auth/send-code', { data: { email } });
  expect(sendRes.status()).toBe(200);
  const { devCode } = await sendRes.json();
  const verifyRes = await request.post('/api/auth/verify-code', {
    data: { email, code: devCode, nickname },
  });
  expect(verifyRes.status()).toBe(200);
  const data = await verifyRes.json();
  return data.user as { id: string; email: string; nickname: string };
}

test.describe.serial('社区迭代核心功能 E2E 草案', () => {
  test('1. 左右布局导航、底部个人资料弹出菜单与退出登录', async ({ page }) => {
    await page.setViewportSize({ width: 1280, height: 800 });
    const user = await loginUser(page.request, makeEmail('layout'), '小光测试');

    await page.goto('/');
    await expect(page.getByText('动态').first()).toBeVisible();
    await expect(page.getByText('私信').first()).toBeVisible();
    await expect(page.getByText('主页').first()).toBeVisible();

    const profileBtn = page
      .getByRole('button', { name: new RegExp(`${user.nickname}|个人资料`) })
      .first();
    await expect(profileBtn).toBeVisible();
    await profileBtn.click();

    const logoutBtn = page.getByRole('button', { name: /退出登录/i }).or(page.getByRole('menuitem', { name: /退出登录/i })).first();
    await expect(logoutBtn).toBeVisible();
    await logoutBtn.click();

    await expect.poll(async () => (await (await page.request.get('/api/auth/me')).json()).authenticated).toBe(false);
  });

  test('2. 个人主页资料、关注粉丝、评论回复与四维记录闭环', async ({ page, browser }) => {
    const ctxB = await browser.newContext();
    try {
      const userA = await loginUser(page.request, makeEmail('prof-a'), '创作者A');
      const userB = await loginUser(ctxB.request, makeEmail('prof-b'), '旅人B');

      const uploadRes = await page.request.post('/api/uploads', {
        multipart: { file: { name: 'avatar.png', mimeType: 'image/png', buffer: PNG_32X32 } },
      });
      expect(uploadRes.status()).toBe(201);
      const { url: avatarUrl } = await uploadRes.json();

      const patchRes = await page.request.patch('/api/auth/profile', {
        data: { nickname: '创作者A新版', bio: '热爱摄影与咖啡的社区记录者', avatarUrl },
      });
      expect(patchRes.status()).toBe(200);

      const postRes = await page.request.post('/api/posts', {
        data: { title: `主页发帖-${Date.now()}`, content: '用于校验个人主页历史发帖与互动' },
      });
      expect(postRes.status()).toBe(201);
      const postId = (await postRes.json()).post.id;

      await page.request.post(`/api/posts/${postId}/like`);
      const commentRes = await ctxB.request.post(`/api/posts/${postId}/comments`, {
        data: { content: '拍得真不错！' },
      });
      expect(commentRes.status()).toBe(201);
      const commentId = (await commentRes.json()).comment.id;

      const replyRes = await page.request.post(`/api/posts/${postId}/comments/${commentId}/replies`, {
        data: { content: '谢谢喜欢，欢迎来玩' },
      });
      expect(replyRes.status()).toBe(201);

      const followRes = await page.request.post(`/api/users/${userB.id}/follow`);
      expect(followRes.status()).toBe(200);
      expect((await followRes.json()).following).toBe(true);

      await page.goto('/');
      await page.getByRole('button', { name: /主页/ }).or(page.getByRole('link', { name: /主页/ })).first().click();
      await expect(page.getByText('创作者A新版').first()).toBeVisible();
      await expect(page.getByText('热爱摄影与咖啡的社区记录者').first()).toBeVisible();

      for (const tab of ['posts', 'likes', 'comments', 'replies']) {
        const actRes = await page.request.get(`/api/users/${userA.id}/activity?tab=${tab}`);
        expect(actRes.status()).toBe(200);
      }
    } finally {
      await ctxB.close();
    }
  });

  test('3. 私信收发与未读已读闭环', async ({ page, browser }) => {
    const ctxB = await browser.newContext();
    try {
      const userA = await loginUser(page.request, makeEmail('dm-a'), '私信甲');
      const userB = await loginUser(ctxB.request, makeEmail('dm-b'), '私信乙');
      const msgText = `你好，交流一下摄影参数-${Date.now()}`;

      const sendDm = await page.request.post(`/api/messages/with/${userB.id}`, {
        data: { content: msgText },
      });
      expect(sendDm.status()).toBe(201);

      const convB = await ctxB.request.get('/api/messages/conversations');
      expect(convB.status()).toBe(200);
      const convBJson = await convB.json();
      expect(convBJson.totalUnread).toBeGreaterThanOrEqual(1);

      const threadB = await ctxB.request.get(`/api/messages/with/${userA.id}`);
      expect(threadB.status()).toBe(200);
      const threadBJson = await threadB.json();
      expect(threadBJson.messages.some((m: { content: string }) => m.content === msgText)).toBe(true);

      const convBAfter = await ctxB.request.get('/api/messages/conversations');
      expect((await convBAfter.json()).totalUnread).toBe(0);
    } finally {
      await ctxB.close();
    }
  });

  test('4. 发布图文图片裁剪编辑流程', async ({ page }) => {
    await page.setViewportSize({ width: 1280, height: 800 });
    await loginUser(page.request, makeEmail('crop'), '裁剪测试员');
    await page.goto('/');

    await page.getByRole('button', { name: /发布图文/ }).first().click();
    await page.locator('input[type="file"]').first().setInputFiles({
      name: 'sample.png',
      mimeType: 'image/png',
      buffer: PNG_32X32,
    });

    const cropTrigger = page.getByRole('button', { name: /裁剪|编辑/i }).first();
    await expect(cropTrigger).toBeVisible();
    await cropTrigger.click();

    const confirmCropBtn = page.getByRole('button', { name: /确认裁剪|应用裁剪|确认|完成/i }).first();
    await expect(confirmCropBtn).toBeVisible();
    await confirmCropBtn.click();

    const title = `裁剪发帖-${Date.now()}`;
    await page.getByPlaceholder(/标题/i).first().fill(title);
    await page.locator('textarea').first().fill('已使用前端裁剪工具完成构图调整');
    await page.getByRole('button', { name: /立即发布/i }).last().click();
    await expect(page.getByText(title).first()).toBeVisible();
  });
});

