import { test, expect, type APIRequestContext } from '@playwright/test';

const PNG_32X32 = Buffer.from(
  'iVBORw0KGgoAAAANSUhEUgAAACAAAAAgCAIAAAD8GO2jAAAAKklEQVR4nGP4Yh9HU8QwasGoBaMWjFowasGoBaMWjFowasGoBaMWDBULAN4gRFtH0KHXAAAAAElFTkSuQmCC',
  'base64'
);

function makeEmail(prefix: string): string {
  const rand = Math.random().toString(36).slice(2, 7);
  return `${prefix}-${Date.now()}-${rand}@example.com`;
}

async function loginUser(
  request: APIRequestContext,
  email: string,
  nickname: string
): Promise<{ id: string; email: string; nickname: string }> {
  const sendRes = await request.post('/api/auth/send-code', { data: { email } });
  expect(sendRes.status(), 'send-code 应返回 200').toBe(200);
  const sendJson = await sendRes.json();
  expect(sendJson.devCode).toMatch(/^\d{6}$/);

  const verifyRes = await request.post('/api/auth/verify-code', {
    data: { email, code: sendJson.devCode, nickname },
  });
  expect(verifyRes.status(), 'verify-code 应返回 200').toBe(200);
  const verifyJson = await verifyRes.json();
  expect(verifyJson.ok).toBe(true);
  return verifyJson.user;
}

test.describe.serial('社区初期迭代（个人主页、私信、图片裁剪、左右布局）加固盲测套件', () => {
  test('1. 健康检查、左右分栏几何结构、左侧导航项与底部个人资料退出登录', async ({ page }) => {
    const pageErrors: string[] = [];
    page.on('pageerror', (err) => pageErrors.push(err.message));
    await page.setViewportSize({ width: 1280, height: 800 });

    const healthRes = await page.request.get('/api/health');
    expect(healthRes.status()).toBe(200);
    expect((await healthRes.json()).ok).toBe(true);

    const nick = `导航用户${Date.now().toString().slice(-4)}`;
    await loginUser(page.request, makeEmail('nav-user'), nick);

    await page.goto('/');
    await expect(page.locator('body')).toBeVisible();
    // 守护隐藏后台路由：公开社区禁止出现 /admin 链接
    await expect(page.locator('a[href="/admin"]')).toHaveCount(0);
    await expect(page.locator('a[href="/admin/"]')).toHaveCount(0);

    // 验证左侧导航栏存在「动态」「私信」「主页」以及左右布局几何关系
    const sidebar = page.locator('aside, nav').first();
    const mainArea = page.locator('main').first();
    await expect(sidebar).toBeVisible({ timeout: 10000 });
    await expect(mainArea).toBeVisible({ timeout: 10000 });

    const sidebarBox = await sidebar.boundingBox();
    const mainBox = await mainArea.boundingBox();
    expect(sidebarBox, '左侧导航栏应具备可见宽度').not.toBeNull();
    expect(mainBox, '右侧主内容区应具备可见宽度').not.toBeNull();
    if (sidebarBox && mainBox) {
      expect(sidebarBox.x).toBeLessThan(mainBox.x);
      expect(mainBox.x).toBeGreaterThanOrEqual(sidebarBox.x + sidebarBox.width - 12);
    }

    const feedNav = sidebar
      .getByRole('button', { name: /动态/ })
      .or(sidebar.getByRole('link', { name: /动态/ }))
      .first();
    const dmNav = sidebar
      .getByRole('button', { name: /私信/ })
      .or(sidebar.getByRole('link', { name: /私信/ }))
      .first();
    const homeNav = sidebar
      .getByRole('button', { name: /主页/ })
      .or(sidebar.getByRole('link', { name: /主页/ }))
      .first();

    await expect(feedNav).toBeVisible();
    await expect(dmNav).toBeVisible();
    await expect(homeNav).toBeVisible();

    // 导航切换至「主页」与「私信」再切回「动态」
    await homeNav.click();
    await expect(mainArea.getByText(nick).first()).toBeVisible({ timeout: 10000 });
    await dmNav.click();
    await expect(mainArea).toBeVisible();
    await feedNav.click();

    // 点击左侧底部个人资料按钮，弹出包含「退出登录」的选项并完成登出
    const profileTrigger = sidebar
      .getByRole('button', { name: new RegExp(`${nick}|个人资料|账号`, 'i') })
      .last();
    await expect(profileTrigger).toBeVisible();
    await profileTrigger.click();

    const logoutOption = page
      .getByRole('menuitem', { name: /退出登录/i })
      .or(page.getByRole('button', { name: /退出登录/i }))
      .first();
    await expect(logoutOption).toBeVisible({ timeout: 10000 });

    const logoutPromise = page.waitForResponse(
      (res) => res.url().includes('/api/auth/logout') && res.request().method() === 'POST'
    );
    await logoutOption.click();
    const logoutRes = await logoutPromise;
    expect(logoutRes.status()).toBe(200);

    const meAfterLogout = await (await page.request.get('/api/auth/me')).json();
    expect(meAfterLogout.authenticated).toBe(false);
    expect(pageErrors, '页面切换与登出不应出现未捕获前端异常').toEqual([]);
  });

  test('2. 个人主页资料修改、安全边界、关注粉丝与评论二级回复闭环', async ({ page, browser }) => {
    await page.setViewportSize({ width: 1280, height: 800 });
    const ctxB = await browser.newContext();
    const anonCtx = await browser.newContext();
    try {
      const emailA = makeEmail('social-a');
      const emailB = makeEmail('social-b');
      const userA = await loginUser(page.request, emailA, '星光作者');
      const userB = await loginUser(ctxB.request, emailB, '漫游旅人');

      // 未登录修改资料、关注、发回复必须返回 401
      expect(
        (await anonCtx.request.patch('/api/auth/profile', { data: { bio: 'unauth' } })).status()
      ).toBe(401);
      expect((await anonCtx.request.post(`/api/users/${userB.id}/follow`)).status()).toBe(401);

      // 非法 avatarUrl 协议（XSS 注入）与超长简介应被 400 拦截
      const xssAvatar = await page.request.patch('/api/auth/profile', {
        data: { avatarUrl: 'javascript:alert(1)' },
      });
      expect(xssAvatar.status()).toBe(400);

      const longBio = await page.request.patch('/api/auth/profile', {
        data: { bio: '简'.repeat(205) },
      });
      expect(longBio.status()).toBe(400);

      // 上传合法头像并更新个人简介与昵称
      const avatarUpload = await page.request.post('/api/uploads', {
        multipart: {
          file: { name: 'avatar.png', mimeType: 'image/png', buffer: PNG_32X32 },
        },
      });
      expect(avatarUpload.status()).toBe(201);
      const { url: avatarUrl } = await avatarUpload.json();

      const newNick = `星光新名${Date.now().toString().slice(-4)}`;
      const newBio = '记录城市光影、手冲咖啡与胶片日常。';
      const updateRes = await page.request.patch('/api/auth/profile', {
        data: { nickname: newNick, bio: newBio, avatarUrl },
      });
      expect(updateRes.status()).toBe(200);
      const updateJson = await updateRes.json();
      expect(updateJson.user.bio).toBe(newBio);
      expect(updateJson.user.avatarUrl).toBe(avatarUrl);

      // 隐私边界：用户 B 访问用户 A 的公开主页时，响应中严禁泄露用户 A 的 email
      const publicProfileRes = await ctxB.request.get(`/api/users/${userA.id}`);
      expect(publicProfileRes.status()).toBe(200);
      const publicProfileText = await publicProfileRes.text();
      expect(publicProfileText, '他人主页公开接口不得泄露邮箱').not.toContain(emailA);
      const publicProfileJson = JSON.parse(publicProfileText);
      expect(publicProfileJson.user.nickname).toBe(newNick);
      expect(publicProfileJson.user.bio).toBe(newBio);
      expect(publicProfileJson.user.avatarUrl).toBe(avatarUrl);

      // 禁止关注自己，关注不存在用户返回 404
      const selfFollow = await page.request.post(`/api/users/${userA.id}/follow`);
      expect(selfFollow.status()).toBe(400);
      const ghostFollow = await page.request.post('/api/users/non-existent-user-id/follow');
      expect(ghostFollow.status()).toBe(404);

      // 关注 -> 粉丝列表核对 -> 取消关注 -> 再次关注，校验计数一致性
      const f1 = await page.request.post(`/api/users/${userB.id}/follow`);
      expect(f1.status()).toBe(200);
      const f1Json = await f1.json();
      expect(f1Json.following).toBe(true);
      expect(f1Json.followersCount).toBe(1);

      const badFollowsType = await page.request.get(`/api/users/${userA.id}/follows?type=invalid`);
      expect(badFollowsType.status()).toBe(400);

      const followingList = await (await page.request.get(`/api/users/${userA.id}/follows?type=following`)).json();
      expect(followingList.total).toBe(1);
      expect(followingList.users.some((u: { id: string }) => u.id === userB.id)).toBe(true);

      const followersList = await (await page.request.get(`/api/users/${userB.id}/follows?type=followers`)).json();
      expect(followersList.total).toBe(1);
      expect(followersList.users.some((u: { id: string }) => u.id === userA.id)).toBe(true);

      const f2 = await page.request.post(`/api/users/${userB.id}/follow`);
      expect(f2.status()).toBe(200);
      expect((await f2.json()).following).toBe(false);
      const f3 = await page.request.post(`/api/users/${userB.id}/follow`);
      expect(f3.status()).toBe(200);
      expect((await f3.json()).followersCount).toBe(1);

      // 发帖、点赞、评论与二级回复全链路及边界校验
      const postTitle = `主页四维校验帖-${Date.now()}`;
      const postRes = await page.request.post('/api/posts', {
        data: { title: postTitle, content: '测试历史发帖、点赞、评论和回复联动' },
      });
      expect(postRes.status()).toBe(201);
      const postId = (await postRes.json()).post.id;

      const otherPostRes = await ctxB.request.post('/api/posts', {
        data: { title: `另一篇帖子-${Date.now()}`, content: '用于校验跨帖回复隔离' },
      });
      const otherPostId = (await otherPostRes.json()).post.id;

      await page.request.post(`/api/posts/${postId}/like`);
      const commentText = `一级评论-${Date.now()}`;
      const commentRes = await ctxB.request.post(`/api/posts/${postId}/comments`, {
        data: { content: commentText },
      });
      expect(commentRes.status()).toBe(201);
      const commentId = (await commentRes.json()).comment.id;

      // 空回复返回 400；跨帖 commentId 返回 404
      const emptyReply = await page.request.post(`/api/posts/${postId}/comments/${commentId}/replies`, {
        data: { content: '   ' },
      });
      expect(emptyReply.status()).toBe(400);

      const crossPostReply = await page.request.post(
        `/api/posts/${otherPostId}/comments/${commentId}/replies`,
        { data: { content: '跨帖非法回复' } }
      );
      expect(crossPostReply.status()).toBe(404);

      const replyText = `二级回复-${Date.now()}`;
      const replyRes = await page.request.post(`/api/posts/${postId}/comments/${commentId}/replies`, {
        data: { content: replyText },
      });
      expect(replyRes.status()).toBe(201);

      // 验证帖子详情嵌套返回回复
      const detailJson = await (await page.request.get(`/api/posts/${postId}`)).json();
      const targetComment = detailJson.comments.find((c: { id: string }) => c.id === commentId);
      expect(targetComment).toBeTruthy();
      expect(
        Array.isArray(targetComment.replies) &&
          targetComment.replies.some((r: { content: string }) => r.content === replyText)
      ).toBe(true);

      // 验证个人主页四维活动接口与非法 tab 拦截
      expect((await page.request.get(`/api/users/${userA.id}/activity?tab=badtab`)).status()).toBe(400);
      const actPosts = await (await page.request.get(`/api/users/${userA.id}/activity?tab=posts`)).json();
      expect(actPosts.items.some((p: { id: string }) => p.id === postId)).toBe(true);
      const actLikes = await (await page.request.get(`/api/users/${userA.id}/activity?tab=likes`)).json();
      expect(actLikes.items.some((p: { id: string }) => p.id === postId)).toBe(true);
      const actCommentsB = await (await ctxB.request.get(`/api/users/${userB.id}/activity?tab=comments`)).json();
      expect(actCommentsB.items.some((c: { content: string }) => c.content === commentText)).toBe(true);
      const actRepliesA = await (await page.request.get(`/api/users/${userA.id}/activity?tab=replies`)).json();
      expect(actRepliesA.items.some((r: { content: string }) => r.content === replyText)).toBe(true);

      // 在浏览器 UI 中进入个人主页核对头像、简介、发帖及标签页切换
      await page.goto('/');
      const sidebar = page.locator('aside, nav').first();
      await sidebar
        .getByRole('button', { name: /主页/ })
        .or(sidebar.getByRole('link', { name: /主页/ }))
        .first()
        .click();

      await expect(page.getByText(newNick).first()).toBeVisible({ timeout: 10000 });
      await expect(page.getByText(newBio).first()).toBeVisible();
      await expect(page.getByText(postTitle).first()).toBeVisible();

      const repliesTab = page
        .getByRole('tab', { name: /回复/ })
        .or(page.getByRole('button', { name: /回复/ }))
        .first();
      await expect(repliesTab).toBeVisible();
      await repliesTab.click();
      await expect(page.getByText(replyText).first()).toBeVisible({ timeout: 10000 });
    } finally {
      await ctxB.close();
      await anonCtx.close();
    }
  });

  test('3. 私信权限隔离、边界校验、未读已读回执与 UI 聊天交互', async ({ page, browser }) => {
    await page.setViewportSize({ width: 1280, height: 800 });
    const ctxB = await browser.newContext();
    const ctxC = await browser.newContext();
    const anonCtx = await browser.newContext();
    try {
      const userA = await loginUser(page.request, makeEmail('dm-a'), '私信发送者');
      const userB = await loginUser(ctxB.request, makeEmail('dm-b'), '私信接收者');
      await loginUser(ctxC.request, makeEmail('dm-c'), '无关旁观者');

      // 未登录访问私信接口必须返回 401
      expect((await anonCtx.request.get('/api/messages/conversations')).status()).toBe(401);
      expect(
        (await anonCtx.request.post(`/api/messages/with/${userB.id}`, { data: { content: 'hi' } })).status()
      ).toBe(401);

      // 边界校验：禁止给自己发私信、禁止空内容/超长内容、不存在用户返回 404
      expect(
        (await page.request.post(`/api/messages/with/${userA.id}`, { data: { content: 'self' } })).status()
      ).toBe(400);
      expect(
        (await page.request.post(`/api/messages/with/${userB.id}`, { data: { content: '   ' } })).status()
      ).toBe(400);
      expect(
        (
          await page.request.post(`/api/messages/with/${userB.id}`, {
            data: { content: '信'.repeat(2005) },
          })
        ).status()
      ).toBe(400);
      expect(
        (
          await page.request.post('/api/messages/with/non-existent-peer', {
            data: { content: 'hello' },
          })
        ).status()
      ).toBe(404);

      // 用户 A 给用户 B 发送私信
      const secretMsg = `仅限双方可见的私信-${Date.now()}`;
      const sendRes = await page.request.post(`/api/messages/with/${userB.id}`, {
        data: { content: secretMsg },
      });
      expect(sendRes.status()).toBe(201);

      // 权限隔离：用户 C 绝不可在会话列表或聊天记录中看到 A 与 B 的私信
      const convCText = await (await ctxC.request.get('/api/messages/conversations')).text();
      expect(convCText).not.toContain(secretMsg);
      const threadCText = await (await ctxC.request.get(`/api/messages/with/${userA.id}`)).text();
      expect(threadCText).not.toContain(secretMsg);

      // 用户 B 校验未读数并在 UI 私信界面打开会话、验证未读清零与回复发送
      const convBPre = await (await ctxB.request.get('/api/messages/conversations')).json();
      expect(convBPre.totalUnread).toBeGreaterThanOrEqual(1);

      const pageB = await ctxB.newPage();
      await pageB.setViewportSize({ width: 1280, height: 800 });
      await pageB.goto('/');
      const sidebarB = pageB.locator('aside, nav').first();
      await sidebarB
        .getByRole('button', { name: /私信/ })
        .or(sidebarB.getByRole('link', { name: /私信/ }))
        .first()
        .click();

      const peerItem = pageB.getByText(userA.nickname).first();
      await expect(peerItem).toBeVisible({ timeout: 10000 });
      await peerItem.click();
      await expect(pageB.getByText(secretMsg).first()).toBeVisible({ timeout: 10000 });

      // 点开会话后未读数应自动清零
      await expect
        .poll(async () => (await (await ctxB.request.get('/api/messages/conversations')).json()).totalUnread)
        .toBe(0);

      // 在 UI 中回复一条私信并验证持久化
      const replyDm = `收到啦回复你-${Date.now()}`;
      const dmInput = pageB
        .getByPlaceholder(/私信|消息|说点什么|输入/i)
        .or(pageB.locator('main textarea, main input[type="text"]'))
        .first();
      await expect(dmInput).toBeVisible();
      await dmInput.fill(replyDm);

      const replyPostPromise = pageB.waitForResponse(
        (res) => res.url().includes(`/api/messages/with/${userA.id}`) && res.request().method() === 'POST'
      );
      const sendDmBtn = pageB.locator('main').getByRole('button', { name: /发送/i }).first();
      await sendDmBtn.click();
      const replyPostRes = await replyPostPromise;
      expect(replyPostRes.status()).toBe(201);
      await expect(pageB.getByText(replyDm).first()).toBeVisible();
      await pageB.close();
    } finally {
      await ctxB.close();
      await ctxC.close();
      await anonCtx.close();
    }
  });

  test('4. 发布图文集成图片裁剪编辑（比例/旋转/确认裁剪）与持久化发布', async ({ page }) => {
    await page.setViewportSize({ width: 1280, height: 800 });
    await loginUser(page.request, makeEmail('crop-e2e'), '构图达人');
    await page.goto('/');

    const composeBtn = page.getByRole('button', { name: /发布图文/i }).first();
    await expect(composeBtn).toBeVisible({ timeout: 10000 });
    await composeBtn.click();

    const fileInput = page.locator('input[type="file"]').first();
    await fileInput.setInputFiles({
      name: 'original-photo.png',
      mimeType: 'image/png',
      buffer: PNG_32X32,
    });

    // 打开裁剪/编辑弹窗，交互切换比例与旋转后确认裁剪
    const cropBtn = page.getByRole('button', { name: /裁剪|编辑/i }).first();
    await expect(cropBtn).toBeVisible({ timeout: 10000 });
    await cropBtn.click();

    const ratioBtn = page.getByRole('button', { name: /1:1|4:3|16:9/ }).first();
    if (await ratioBtn.isVisible().catch(() => false)) {
      await ratioBtn.click();
    }
    const rotateBtn = page.getByRole('button', { name: /旋转/i }).first();
    if (await rotateBtn.isVisible().catch(() => false)) {
      await rotateBtn.click();
    }

    const confirmCropBtn = page
      .getByRole('button', { name: /确认裁剪|应用裁剪|保存裁剪|确认|完成/i })
      .last();
    await expect(confirmCropBtn).toBeVisible({ timeout: 10000 });
    await confirmCropBtn.click();

    // 裁剪完成后填写标题与正文并发布，校验上传与帖子创建成功
    const postTitle = `裁剪构图发布-${Date.now()}`;
    await page
      .getByPlaceholder(/标题|起个/i)
      .or(page.getByLabel(/标题/i))
      .first()
      .fill(postTitle);
    await page
      .getByPlaceholder(/正文|分享|想法/i)
      .or(page.locator('textarea'))
      .first()
      .fill('体验新版图片裁剪与旋转编辑后发布的第一篇图文');

    const uploadPromise = page.waitForResponse(
      (res) => res.url().includes('/api/uploads') && res.request().method() === 'POST'
    );
    const createPostPromise = page.waitForResponse(
      (res) => res.url().endsWith('/api/posts') && res.request().method() === 'POST'
    );

    await page.getByRole('button', { name: /立即发布/i }).last().click();
    const uploadRes = await uploadPromise;
    expect(uploadRes.status()).toBe(201);
    const createRes = await createPostPromise;
    expect(createRes.status()).toBe(201);
    const createdPost = (await createRes.json()).post;
    expect(createdPost.imageUrl).toMatch(/^\/api\/uploads\//);

    await page.reload();
    await expect(page.getByText(postTitle).first()).toBeVisible({ timeout: 10000 });
  });
});

